const staticData = $getWorkflowStaticData('global');
staticData.subscriptionId = $json.body.id;
staticData.expirationTime = $json.body.expirationTime;
staticData.creationTime = $json.body.creationTime;

return {
  subscriptionId: staticData.subscriptionId,
  expirationTime: staticData.expirationTime,
  creationTime: staticData.creationTime,
  reason: $json.reason,
  fallbackRecovery: $json.reason === 'renewal-fallback'
};
